<?php
$b=json_body();require_fields($b,['refreshToken']);$hash=hash('sha256',(string)$b['refreshToken']);$s=db()->prepare('SELECT s.id session_id,u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.refresh_token_hash=? AND s.revoked_at IS NULL AND s.refresh_expires_at>NOW()');$s->execute([$hash]);$u=$s->fetch();if(!$u)fail(401,'REFRESH_EXPIRED_OR_REVOKED','The refresh token is invalid or expired.');ensure_active_account((string)$u['id']);$access=bin2hex(random_bytes(32));$refresh=bin2hex(random_bytes(32));$update=db()->prepare('UPDATE sessions SET access_token_hash=?,refresh_token_hash=?,access_expires_at=DATE_ADD(NOW(),INTERVAL 1 HOUR),refresh_expires_at=DATE_ADD(NOW(),INTERVAL 30 DAY) WHERE id=? AND refresh_token_hash=?');$update->execute([hash('sha256',$access),hash('sha256',$refresh),$u['session_id'],$hash]);if($update->rowCount()!==1)fail(409,'ROTATION_REPLAY_DETECTED','The refresh token has already been rotated.');out(session_result($access,$refresh,$u));
